const LET = /[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]{2}/;
const NUM_ES = /\d{1,3}(?:\.\d{3})+(?:,\d+)?(?!\d)|\d+(?:,\d+)?/g;
// (a decimal point never inside a section number: A.1.3.4 is 1, 3, 4)
const NUM_EN = /\d{1,3}(?:,\d{3})+(?:\.\d+)?(?!\d)|(?<![A-Za-z\d]\.)\d+\.\d+(?!\.\d)|\d+/g;
const cv = t => t.replace(/[.,]/g, c => c === '.' ? ',' : '.');
const MK = (ty, i) => '\uE000' + ty + String.fromCharCode(0xE100 + i);
// place names: departments, municipalities (NSR-10 A-4) and the cities of the site. A name that is also an ordinary word
// ("Prado", "Toca") does no harm: names are kept as they are, and an English text that does not use one simply leaves it out.
let NRE = null;
const nameRe = () => { if (NRE) return NRE; const set = new Set();
  try { a4().forEach(d => { set.add(d.d); d.m.forEach(m => set.add(m.n)); }); CIU.forEach(c => set.add(c.n)); } catch (e) {}
  const list = [...set].filter(n => n && n.length > 2).sort((a, b) => b.length - a.length).map(n => n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  NRE = new RegExp('(?<![\\p{L}\\p{N}])(?:' + list.join('|') + ')(?![\\p{L}\\p{N}])', 'gu'); return NRE; };
