const fill = (v, n) => v.replace(/\uE000([TNA])(.)/g, (m, ty, c) => { const i = c.charCodeAt(0) - 0xE100; return ty === 'T' ? n.tags[i] : ty === 'N' ? cv(n.nums[i]) : n.nms[i]; });
