const SKIP = new Set(['script', 'style', 'template', 'textarea', 'noscript', 'canvas', 'iframe', 'video', 'audio', 'input']);
const INL = new Set(['a', 'b', 'strong', 'i', 'em', 'span', 'small', 'sub', 'sup', 'br', 'abbr', 'code', 'mark', 'u', 's', 'q', 'cite', 'wbr', 'tspan', 'bdi', 'dfn', 'kbd']);
