const NOTE = 'Our team works in Spanish. You can write to us in English and we will get back to you.';
const enHref = h => { const m = /^\/([\w-]*)\/?(\?.*)?$/.exec(h); if (!m || !m[1] || m[1] === 'en') return null; try { return routes.some(r => r.re.test(m[1])) ? k2p(m[1], 'en') + (m[2] || '') : null; } catch (e) { return null; } };
